SELECT c.id,c.flow_run_id,c.consumer_kind,c.graph_revision_id,c.edge_partition_id,c.subtask_id,c.task_run_id,c.input_port_id,c.input_port_uid,c.subscriber_uid,c.input_stream_id,c.output_stream_id,c.owner_id,c.attempt,c.owner_epoch,c.completed_through,c.inflight_sequence,(c.delivery_id IS NOT NULL) AS delivery_present FROM stream_consumer c JOIN stream_graph_revision g ON g.id=c.graph_revision_id WHERE g.flow_run_id=$1 AND g.id=$2 ORDER BY c.id
